#!/bin/bash
sed -i 's/async getPublicProfile(userId: string): Promise<SocialPlayer | null> {/async getPublicProfile(userId: string, currentUserId?: string): Promise<SocialPlayer | null> {/g' src/services/social.ts
sed -i 's/return this.formatUserToSocialPlayer(userDoc.data());/const p = this.formatUserToSocialPlayer(userDoc.data());\n    if (currentUserId) {\n      p.isFollowing = await this.checkIsFollowing(currentUserId, userId);\n      const friendStatus = await this.checkFriendshipStatus(currentUserId, userId);\n      p.isFriend = friendStatus === '"'"'friends'"'"';\n      if (friendStatus === '"'"'request_sent'"'"') p.friendRequestStatus = '"'"'PENDING_SENT'"'"';\n      else if (friendStatus === '"'"'request_received'"'"') p.friendRequestStatus = '"'"'PENDING_RECEIVED'"'"';\n      else p.friendRequestStatus = '"'"'NONE'"'"';\n    }\n    return p;/g' src/services/social.ts
